// --- CONFIG ---
const MAX_CHARS = 4900;     // Google TTS limit (characters, not bytes)
const PARA_BREAK = 600;     // pause between paragraphs (ms)

// --- 1️⃣ Get and parse model output ---
let outer = String($json.output || '').trim();
let payload;

// Sometimes the model returns a stringified JSON object
try {
  payload = JSON.parse(outer);
} catch {
  // Or sometimes n8n already parses it as an object
  payload = $json.output;
}

// --- 2️⃣ Extract the real script ---
let script = String(payload?.script || '').trim();

// remove <script> wrapper if system prompt still uses it
script = script.replace(/^<script>/i, '').replace(/<\/script>$/i, '').trim();

// --- 3️⃣ Verify true character count ---
const actualChars = script.length;
const reportedChars = Number(payload?.chars || 0);

console.log(`Actual script length: ${actualChars}, model reported: ${reportedChars}`);

if (actualChars > 3800) {
  console.warn(`⚠️ Script exceeds 3,800-char budget (${actualChars}). Will still attempt SSML generation.`);
}

// --- 4️⃣ Split into paragraphs ---
const paragraphs = script.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);

// --- 5️⃣ Escape XML-sensitive characters in text ---
const esc = (t) =>
  t.replace(/&/g, '&amp;')
   .replace(/</g, '&lt;')
   .replace(/>/g, '&gt;');

// --- 6️⃣ Assemble SSML ---
let assembled = '';
for (const p of paragraphs) {
  const node = `<p>${esc(p)}</p>`;
  const test = assembled
    ? `${assembled}<break time="${PARA_BREAK}ms"/>${node}`
    : node;

  const candidate = `<speak>${test}</speak>`;
  if (candidate.length > MAX_CHARS) break; // stop before Google limit
  assembled = test;
}

if (!assembled) throw new Error('No speakable content after processing.');

const ssml = `<speak>${assembled}</speak>`;
const total = ssml.length;

// --- 7️⃣ Return SSML object for Google TTS node ---
return [{
  json: {
    ssml,
    chars: total,
    fileName: 'csd_audio.mp3'
  }
}];

