// Code node (per-item). Input: item.json.output (HTML from AI Agent)
// Output: [{ json: { data: "<!DOCTYPE html>..."} }, ...]  // ONLY the HTML in `data`

function decodeEntities(s) {
  return s
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

return $input.all().map(({ json }) => {
  let html = String(json.output || '').trim();

  // Strip code fences
  html = html.replace(/^```(?:html)?\s*/i, '').replace(/```$/i, '').trim();

  // Decode if escaped
  if (!/^<html[\s>]/i.test(html) && /&lt;html/i.test(html)) {
    html = decodeEntities(html);
  }

  // Remove any accidental table wrappers
  html = html.replace(/<\/?(table|thead|tbody|tr|td|th)\b[^>]*>/gi, '').trim();

  // Add <!DOCTYPE html> if missing and we have <html>
  if (/^<html[\s>]/i.test(html) && !/^<!DOCTYPE html>/i.test(html)) {
    html = '<!DOCTYPE html>\n' + html;
  }

  // Emit only the HTML under `data`
  return { json: { data: html } };
});

